xopen: Open compressed files transparently.
"""
import sys
import os
import io
import time
import gzip
import subprocess
import tempfile

# ---------------------------------------------------------------------------
# Python version helpers
# ---------------------------------------------------------------------------
IS_PY3 = sys.version_info >= (3,)


# ---------------------------------------------------------------------------
# Optional imports
# ---------------------------------------------------------------------------
try:
    import bz2
except ImportError:
    bz2 = None

try:
    import lzma
except ImportError:
    lzma = None


# ---------------------------------------------------------------------------
# Context manager mixin
# ---------------------------------------------------------------------------
class Closing(object):
    """Mixin for file-like objects that adds context manager support and
    safe finalization via ``__del__``.
    """

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()
        return None

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass


# ---------------------------------------------------------------------------
# bz2 compatibility wrapper (Python 2.6)
# ---------------------------------------------------------------------------
if bz2 is not None:
    class ClosingBZ2File(bz2.BZ2File, Closing):
        """A better BZ2File that supports the context manager protocol.

        This is only needed on Python 2.6.
        """
        pass


# ---------------------------------------------------------------------------
# Subprocess-backed gzip reader
# ---------------------------------------------------------------------------
class PipedGzipReader(Closing):
    """Read a gzip-compressed file by spawning ``gzip -cd`` and exposing
    its stdout as a file-like object.
    """

    def __init__(self, path, mode='r'):
        if mode not in ('r', 'rt', 'rb'):
            raise ValueError(
                "Mode is '{0}', but it must be 'r', 'rt' or 'rb'".format(mode)
            )

        self.name = path
        self.closed = False

        self.process = subprocess.Popen(
            ['gzip', '-cd', path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

        if IS_PY3:
            if 'b' not in mode:
                self._file = io.TextIOWrapper(self.process.stdout)
                self._stderr = io.TextIOWrapper(self.process.stderr)
            else:
                self._file = self.process.stdout
                self._stderr = self.process.stderr
        else:
            self._file = self.process.stdout
            self._stderr = self.process.stderr

        time.sleep(0.01)
        self._raise_if_error()

    def read(self, *args):
        data = self._file.read(*args)
        if not args or args[0] <= 0:
            self.process.wait()
        self._raise_if_error()
        return data

    def __iter__(self):
        for line in self._file:
            yield line
        self.process.wait()
        self._raise_if_error()

    def close(self):
        self.closed = True
        if self.process.poll() is None:
            self.process.terminate()
        self._raise_if_error()

    def _raise_if_error(self):
        retcode = self.process.poll()
        if retcode is not None and retcode != 0:
            message = self._stderr.read().strip()
            raise IOError(message)


# ---------------------------------------------------------------------------
# Subprocess-backed gzip writer
# ---------------------------------------------------------------------------
class PipedGzipWriter(Closing):
    """Write gzip-compressed output by piping into an external ``pigz`` or
    ``gzip`` process.
    """

    def __init__(self, path, mode='wt'):
        if mode not in ('w', 'wt', 'wb', 'a', 'at', 'ab'):
            raise ValueError(
                "Mode is '{0}', but it must be 'w', 'wt', 'wb', 'a', 'at' or 'ab'"
                .format(mode)
            )

        self.name = path
        self.closed = False
        self.program = None

        # Map write/append mode to filesystem open mode
        if 'a' in mode:
            file_mode = 'ab' if 'b' in mode else 'a'
        else:
            file_mode = 'wb' if 'b' in mode else 'w'

        self._outfile = open(path, file_mode)
        self._devnull = open(os.devnull, 'w')

        # Prefer pigz, fall back to gzip
        try:
            self.process = subprocess.Popen(
                ['pigz'],
                stdin=subprocess.PIPE,
                stdout=self._outfile,
                stderr=self._devnull,
                close_fds=True,
            )
            self.program = 'pigz'
        except OSError:
            try:
                self.process = subprocess.Popen(
                    ['gzip'],
                    stdin=subprocess.PIPE,
                    stdout=self._outfile,
                    stderr=self._devnull,
                    close_fds=True,
                )
                self.program = 'gzip'
            except OSError:
                self._outfile.close()
                self._devnull.close()
                raise

        if IS_PY3:
            if 'b' not in mode:
                self._file = io.TextIOWrapper(self.process.stdin)
            else:
                self._file = self.process.stdin
        else:
            self._file = self.process.stdin

    def write(self, arg):
        self._file.write(arg)

    def close(self):
        self.closed = True
        self._file.close()
        retcode = self.process.wait()
        self._outfile.close()
        self._devnull.close()
        if retcode != 0:
            raise IOError(
                "Output {0} process terminated with exit code {1}".format(
                    self.program, retcode
                )
            )


# ---------------------------------------------------------------------------
# Buffering helpers for Python 2.7 gzip fallback
# ---------------------------------------------------------------------------
if IS_PY3:
    buffered_reader = lambda x: x
    buffered_writer = lambda x: x
else:
    if sys.version_info >= (2, 7):
        buffered_reader = lambda x: io.BufferedReader(x)
        buffered_writer = lambda x: io.BufferedWriter(x)
    else:
        buffered_reader = lambda x: x
        buffered_writer = lambda x: x


# ---------------------------------------------------------------------------
# Standard stream dispatch
# ---------------------------------------------------------------------------
def _open_std_stream(mode):
    """Return the appropriate standard stream for the given *mode*."""
    if mode == 'rt':
        return sys.stdin
    elif mode == 'rb':
        return sys.stdin.buffer
    elif mode == 'wt':
        return sys.stdout
    elif mode == 'wb':
        return sys.stdout.buffer
    else:
        # 'at' and 'ab' have no entry in the dispatch table -- lookup failure.
        raise ValueError("mode '{0}' not supported".format(mode))


# ---------------------------------------------------------------------------
# Gzip dispatch
# ---------------------------------------------------------------------------
def _open_gz(filename, mode, compresslevel):
    """Open a ``.gz`` file using the best available backend."""
    if IS_PY3 and 'r' in mode:
        # Python 3 read mode: use stdlib directly
        return gzip.open(filename, mode)

    if 'r' in mode:
        # Read path: try subprocess reader, fall back to gzip.open
        try:
            return PipedGzipReader(filename, mode)
        except OSError:
            return buffered_reader(gzip.open(filename, mode))
    else:
        # Write / append path: try subprocess writer, fall back to gzip.open
        try:
            return PipedGzipWriter(filename, mode)
        except OSError:
            return buffered_writer(
                gzip.open(filename, mode, compresslevel=compresslevel)
            )


# ---------------------------------------------------------------------------
# Bzip2 dispatch
# ---------------------------------------------------------------------------
def _open_bz2(filename, mode):
    """Open a ``.bz2`` file."""
    if bz2 is None:
        raise ImportError(
            "Cannot open bz2 files: The bz2 module is not available"
        )

    if IS_PY3:
        return bz2.open(filename, mode)
    else:
        # Python 2 path
        if mode[0] == 'a':
            raise ValueError(
                "mode '{0}' not supported with BZ2 compression".format(mode)
            )
        if sys.version_info <= (2, 6):
            return ClosingBZ2File(filename, mode)
        else:
            return bz2.BZ2File(filename, mode)


# ---------------------------------------------------------------------------
# XZ dispatch
# ---------------------------------------------------------------------------
def _open_xz(filename, mode):
    """Open a ``.xz`` file."""
    if lzma is None:
        raise ImportError(
            "Cannot open xz files: The lzma module is not available "
            "(use Python 3.3 or newer)"
        )
    return lzma.open(filename, mode)


# ---------------------------------------------------------------------------
# Main public entry point
# ---------------------------------------------------------------------------
def xopen(filename, mode='r', compresslevel=6):
    """Open a file or standard stream, transparently handling compression.

    Parameters
    ----------
    filename : str
        Path to the file, or ``'-'`` for standard input / output.
    mode : str
        Open mode.  Shorthands ``'r'``, ``'w'``, ``'a'`` are expanded to
        text modes ``'rt'``, ``'wt'``, ``'at'``.  Supported modes are
        ``'rt'``, ``'rb'``, ``'wt'``, ``'wb'``, ``'at'``, ``'ab'``.
    compresslevel : int
        Compression level (1-9), only used for gzip fallback writes.

    Returns
    -------
    file-like object
    """
    if not isinstance(filename, str):
        raise ValueError("the filename must be a string")

    # Normalise shorthand modes
    if mode in ('r', 'w', 'a'):
        mode = mode + 't'

    if mode not in ('rt', 'rb', 'wt', 'wb', 'at', 'ab'):
        raise ValueError("mode '{0}' not supported".format(mode))

    # Standard streams
    if filename == '-':
        return _open_std_stream(mode)

    # Dispatch by file extension
    if filename.endswith('.gz'):
        return _open_gz(filename, mode, compresslevel)
    elif filename.endswith('.bz2'):
        return _open_bz2(filename, mode)
    elif filename.endswith('.xz'):
        return _open_xz(filename, mode)
    else:
        return open(filename, mode)
